-- Event photo accuracy sweep 2026-11-09. Each change is guarded by the old image so a newer edit is never overwritten.
-- 1) The event's own photo replaces a site-wide default image (SAMLARC's og:image is a movie-night photo used for every event; the page's own gallery has the tree-lighting photo) or a newsletter cover (Culver City).
UPDATE events SET image='https://samlarc.org/upload/Event/Galleries/2026-01/Tree%20lighting%20%2898%20of%20133%29.jpeg', updated_at=datetime('now') WHERE id='soc-rsm-tree-lighting' AND image='https://samlarc.org/assets/sms_photos/sms_events.jpg';
UPDATE events SET image='https://www.culvercity.gov/files/assets/public/v/1/images/news/2025/holiday-tree-lighting-downtown-culver-city.jpg', updated_at=datetime('now') WHERE id='culver-city-tree-lighting' AND image='https://www.culvercity.gov/files/assets/public/v/1/images/news/2025/culver-city-monthly-newsletter-december-2025.jpg?w=1200';
-- 2) Images that no longer work (the server answers 404, or the picture is blank or a transparent logo) are removed, so the card shows the stock photo for its type instead of a broken or wrong picture.
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='imaginarium-fairplex' AND image='https://momsla.com/wp-content/uploads/2022/11/The-Grove-Holiday-Lights-featured-image.jpg';
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='g17-colton-tree-lighting' AND image='https://i0.wp.com/iecn.com/wp-content/uploads/2025/12/IMG_20251203_200326_490.jpg';
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='g16-la-quinta-resort-tree-lighting' AND image='https://laquintaresort.com/wp-content/uploads/bb-plugin/cache/22168fef007090b8fad32c6deea4164832abd67e-scaled-landscape-401dc94e5c21d26bfab9c162a20d2beb-ac0b3wrqxi7f.jpg';
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='costa-mesa-handels-messiah' AND image='https://www.pacificsymphony.org/storage/slider_galleries/pacificsymphony/136300a09b7382d9184fcedc30c108862a20ca9f.webp';
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='costa-mesa-nutcracker-for-kids' AND image='https://www.pacificsymphony.org/storage/slider_galleries/pacificsymphony/136300a09b7382d9184fcedc30c108862a20ca9f.webp';
UPDATE events SET image=NULL, updated_at=datetime('now') WHERE id='monterey-park-lny' AND image='https://www.montereypark.ca.gov/ImageRepository/Document?documentID=17289';
